"""Deterministic share arithmetic. No model output is trusted here without a check.

Indian practice: fractional entitlements from bonus or merger ratios are pooled,
sold by the company, and paid out in cash, so we floor and record the fraction.
"""
import re
from datetime import date
from fractions import Fraction


def normalise(text):
    return re.sub(r"\s+", " ", text or "").strip().lower()


def verify(actions, source_text):
    """Split actions into those whose evidence appears verbatim in the source, and the rest."""
    haystack = normalise(source_text)
    accepted, rejected = [], []
    for action in actions:
        evidence = normalise(action.get("evidence"))
        if len(evidence) >= 15 and evidence in haystack:
            accepted.append(action)
        else:
            rejected.append({**action, "reason": "evidence not found in the pasted text"})
    return accepted, rejected


def _multiplier(action):
    kind = action["type"]
    if kind == "bonus":
        return 1 + Fraction(action["give"], action["per"])
    if kind == "merger":
        return Fraction(action["give"], action["per"])
    if kind in ("split", "consolidation"):
        return Fraction(str(action["from_fv"])) / Fraction(str(action["to_fv"]))
    if kind == "rename":
        return Fraction(1)
    raise ValueError(f"unknown action type: {kind}")


def _describe(action):
    kind = action["type"]
    if kind == "bonus":
        return f"Bonus {action['give']}:{action['per']}"
    if kind == "merger":
        return f"Merged into {action['into']} ({action['give']} for every {action['per']})"
    if kind in ("split", "consolidation"):
        return f"{kind.title()}: face value Rs {action['from_fv']:g} to Rs {action['to_fv']:g}"
    return f"Renamed to {action['into']}"


def trace(certificate, actions):
    """Walk the share count forward from the certificate date through each action."""
    issued = date.fromisoformat(certificate["issue_date"])
    shares = int(certificate["shares"])
    company = certificate["company"]
    face_value = float(certificate["face_value"])
    timeline = [{
        "date": issued.isoformat(),
        "event": "Certificate issued",
        "company": company,
        "shares": shares,
        "face_value": face_value,
    }]
    skipped = []
    for action in sorted(actions, key=lambda a: a["date"]):
        if date.fromisoformat(action["date"]) <= issued:
            skipped.append({**action, "reason": "happened before the certificate was issued"})
            continue
        exact = shares * _multiplier(action)
        shares = int(exact)  # floor; the fraction is paid in cash
        if action["type"] in ("merger", "rename"):
            company = action["into"]
        if action["type"] in ("split", "consolidation"):
            face_value = float(action["to_fv"])
        timeline.append({
            "date": action["date"],
            "event": _describe(action),
            "company": company,
            "shares": shares,
            "face_value": face_value,
            "fraction_paid_in_cash": float(exact - shares),
            "evidence": action.get("evidence", ""),
        })
    return {
        "company_today": company,
        "shares_today": shares,
        "face_value_today": face_value,
        "growth": f"{shares / int(certificate['shares']):g}x",
        "timeline": timeline,
        "skipped": skipped,
    }


def value(shares, price):
    return round(shares * price, 2) if price else None

"""Claim checklist. Fixed text written by a human, never generated, because a wrong
legal step costs a family months. General guidance only: confirm with the company's
Registrar and Transfer Agent (RTA) or the IEPF Authority before filing anything.
"""


def checklist(certificate, trace_result, holder_deceased=False):
    company = trace_result["company_today"]
    steps = [
        {
            "title": "Check whether the shares or dividends went to IEPF",
            "detail": (
                "If dividends stayed unclaimed for 7 years in a row, the company must move the shares "
                "to the Investor Education and Protection Fund. Search iepf.gov.in by the holder's name, "
                f"folio {certificate['folio']} and the company name ({certificate['company']} and {company})."
            ),
        },
        {
            "title": f"Write to the RTA of {company}",
            "detail": (
                f"Quote folio {certificate['folio']} and certificate no. {certificate['certificate_no']}. "
                "Ask them to confirm the current holding, including bonus and merger shares issued since, "
                "and any unpaid dividends. The RTA's name is on the company's investor page."
            ),
        },
        {
            "title": "Update KYC for the physical folio",
            "detail": "Send PAN, address proof, bank details and a nomination to the RTA (SEBI form ISR-1 and related forms).",
        },
    ]
    if holder_deceased:
        steps.append({
            "title": "Transmission to the legal heir",
            "detail": (
                "Submit the death certificate plus the nomination, a succession certificate or other "
                "legal-heir documents as the RTA asks. SEBI allows simpler documents for smaller holdings."
            ),
        })
    steps += [
        {
            "title": "Dematerialise",
            "detail": (
                "Physical shares can no longer be transferred or sold as paper. Open a demat account and "
                "submit the certificates (or the RTA's Letter of Confirmation) through your depository participant."
            ),
        },
        {
            "title": "If anything is with IEPF: file IEPF-5",
            "detail": (
                "File form IEPF-5 online on the MCA portal, then send the signed copy and documents "
                "to the company's Nodal Officer. One form per company."
            ),
        },
    ]
    return steps

"""Local web app: python -m p2p.server, then open http://localhost:8765"""
import base64
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from . import claim, gemma, ledger

INDEX = Path(__file__).with_name("index.html")
PORT = int(os.environ.get("PORT", "8765"))


def handle_read(payload):
    return gemma.read_certificate(base64.b64decode(payload["image_b64"]))


def handle_trace(payload):
    certificate = payload["certificate"]
    text = payload["actions_text"]
    proposed = gemma.extract_actions(certificate["company"], text)
    accepted, rejected = ledger.verify(proposed, text)
    result = ledger.trace(certificate, accepted)
    result["rejected"] = rejected
    result["value_today"] = ledger.value(result["shares_today"], float(payload.get("price") or 0))
    result["checklist"] = claim.checklist(certificate, result, payload.get("holder_deceased", False))
    result["summary"] = gemma.write_summary(certificate, {
        k: result[k] for k in ("company_today", "shares_today", "growth", "value_today", "timeline")
    }, payload.get("language", "English"))
    return result


ROUTES = {"/api/read": handle_read, "/api/trace": handle_trace}


class Handler(BaseHTTPRequestHandler):
    def _send(self, status, body, content_type="application/json"):
        data = body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", f"{content_type}; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path in ("/", "/index.html"):
            self._send(200, INDEX.read_bytes(), "text/html")
        else:
            self._send(404, {"error": "not found"})

    def do_POST(self):
        route = ROUTES.get(self.path)
        if not route:
            return self._send(404, {"error": "not found"})
        try:
            payload = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
            self._send(200, route(payload))
        except Exception as exc:  # surface model/network errors to the page
            self._send(500, {"error": f"{type(exc).__name__}: {exc}"})


def main():
    print(f"Paper to Portfolio on http://localhost:{PORT}  (model: {gemma.MODEL})")
    ThreadingHTTPServer(("127.0.0.1", PORT), Handler).serve_forever()


if __name__ == "__main__":
    main()

